import './Registrar_Empresa.css'
import React, { useState } from "react";
import { FaSearch, FaUser, FaShoppingCart, FaSignOutAlt } from 'react-icons/fa';

const RegistrarEmpresa = ({ setView }) => {
  const [contactName, setContactName] = useState("");
  const [email, setEmail] = useState("");
  const [comments, setComments] = useState("");
  
  const handleContactNameChange = (e) => {
    setContactName(e.target.value);
  };

  const handleEmailChange = (e) => {
    setEmail(e.target.value);
  };

  const handleCommentsChange = (e) => {
    setComments(e.target.value);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log("Form submitted");
    // Aquí puedes manejar la lógica de envío del formulario
  };

  return (
    <div className="registrar-empresa-container">
      <h1>Registrar Empresa</h1>
      <form id="Highlighted-form" onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="contact-name" className="control-label FaUser">Name</label>
          <div className="controls">
          
            <input
              id="contact-name"
              name="contactName"
              placeholder="Nombre Propietario"
              className="form-control requiredField Highlighted-label"
              type="text"
              value={contactName}
              onChange={handleContactNameChange}
              required
            />
            <i className="fa fa-user icon"></i>
          </div>
        </div>
        <div className="form-group">
          <label htmlFor="contact-mail" className="control-label">Email</label>
          <div className="controls">
            <input
              id="contact-mail"
              name="email"
              placeholder="Correo Empresa"
              className="form-control requiredField Highlighted-label"
              type="email"
              value={email}
              onChange={handleEmailChange}
              required
            />
            <i className="fa fa-envelope icon"></i>
          </div>
        </div>
        <div className="form-group">
          <label htmlFor="contact-message" className="control-label">Message</label>
          <div className="controls">
           sdsdsd
            <textarea
              id="contact-message form-control requiredField Highlighted-label"
              name="comments"
              placeholder="Descripcion"
              className="form-control requiredField Highlighted-label"
              rows="6"
              value={comments}
              onChange={handleCommentsChange}
              required
            ></textarea>
            <i className="fa fa-comment icon"></i>
          </div>
        </div>
        
        <input type="hidden" name="submitted" id="submitted" value="true" />
      </form>
      <div className="btn-regresar" onClick={() => setView("login")}>Regresar</div>
    </div>
  );
}

export default RegistrarEmpresa;
